    ["Report saved: {path}"] = "Informe guardado: {path}",
    ["Running"] = "En marcha",
    ["Save a report file you can send to the developer. API keys, tokens, IDs, microphone audio and conversation text are left out. If the conversation service is not running, a shorter report is made from the files the game can read."] = "Guarda un archivo de informe que puedas enviar al desarrollador. Se omiten las claves de API, los tokens, los ID, el audio del micrófono y el texto de las conversaciones. Si el servicio de conversación no está en marcha, se crea un informe más corto a partir de los archivos que el juego puede leer.",
    ["Saved at {path}"] = "Guardado en {path}",
    ["Saved reports"] = "Informes guardados",
    ["Send the generated report rather than raw log files. Open these locations only if the developer asks for a specific file."] = "Envía el informe generado en lugar de los archivos de registro sin procesar. Abre estas ubicaciones solo si el desarrollador te pide un archivo concreto.",
    ["Short report saved because the conversation service could not build the full report: {path}"] = "Informe breve guardado porque el servicio de conversación no pudo crear el informe completo: {path}",
    ["Short report saved because the conversation service did not answer: {path}"] = "Informe breve guardado porque el servicio de conversación no respondió: {path}",
    ["Short report saved because the conversation service is not running: {path}"] = "Informe breve guardado porque el servicio de conversación no está en marcha: {path}",
    ["Starting"] = "Iniciando",
    ["Support report saved: {path}"] = "Informe de soporte guardado: {path}",
    ["The clipboard is not available here. Read the path from the Last report row."] = "El portapapeles no está disponible aquí. Lee la ruta en la fila Último informe.",
    ["The conversation service runs beside the game. If it is not running, restart the game. Its logs are listed below."] = "El servicio de conversación se ejecuta junto al juego. Si no está en marcha, reinicia el juego. Sus registros se enumeran abajo.",
    ["The conversation service writes bridge.stderr.log, bridge.stdout.log and bridge-service.log in {path}"] = "El servicio de conversación escribe bridge.stderr.log, bridge.stdout.log y bridge-service.log en {path}",
    ["The redscript compiler writes redscript_rCURRENT.log at {path}"] = "El compilador de redscript escribe redscript_rCURRENT.log en {path}",
    ["The report could not be created. Check that the mod folder can be written to, then try again."] = "No se pudo crear el informe. Comprueba que se pueda escribir en la carpeta del mod y vuelve a intentarlo.",
    ["The service launcher writes launcher.log at {path}"] = "El lanzador del servicio escribe launcher.log en {path}",
    ["This is a short report: the conversation service was not available to build the full one."] = "Este es un informe breve: el servicio de conversación no estaba disponible para crear el completo.",
    ["Unknown"] = "Desconocido",
    ["What to do"] = "Qué hacer",
    ["Where the logs are"] = "Dónde están los registros",
    ["the game folder"] = "la carpeta del juego",
    ["the runtime folder of the mod project, or the data folder inside the mod folder"] = "la carpeta de ejecución del proyecto del mod, o la carpeta de datos dentro de la carpeta del mod",
    ["Auto-connect nearby characters"] = "Conexión automática con personajes cercanos",
    ["Prepare the conversation with a character you look at or walk up to, so they answer without a wait. Off by default: the connection is made when you start talking. It uses a little memory and bandwidth, and pauses during combat and scenes."] = "Prepara la conversación con un personaje al que miras o te acercas, para que responda sin esperas. Desactivado por defecto: la conexión se establece cuando empiezas a hablar. Usa algo de memoria y ancho de banda, y se pausa durante combates y escenas.",
    ["Preparing connection to {name}…"] = "Preparando la conexión con {name}…",
    ["Preparing connection to {name}… (turn on Auto-connect to skip this wait)"] = "Preparando la conexión con {name}… (activa «Conexión automática con personajes cercanos» para evitar esta espera)",
    ["Preparing {names}…"] = "Preparando a {names}…",
    ["Connecting {names}…"] = "Conectando con {names}…",
    ["{names} are ready to join when you return to the game."] = "{names} ya pueden unirse cuando vuelvas al juego.",
    ["{names} are ready. Close the phone to join."] = "{names} ya pueden unirse. Cierra el teléfono.",
    ["{names} are joining your party."] = "{names} se están uniendo a tu grupo.",
    ["{names} joined your group."] = "{names} se han unido a tu grupo.",
    ["{first} and {second}"] = "{first} y {second}",
    ["{first}, {second} and {third}"] = "{first}, {second} y {third}",
    ["{first}, {second} and {count} others"] = "{first}, {second} y {count} más",
    ["{count} more companions also failed."] = "{count} acompañantes más tampoco lo consiguieron.",
    ["Change pending. Choose Apply to use it, or Revert to discard it."] = "Cambio pendiente. Elige Aplicar para usarlo o Revertir para descartarlo.",
    ["Changes wait until you choose Apply."] = "Los cambios esperan hasta que elijas Aplicar.",
    ["Changes wait until you choose Apply; Revert discards them. No game restart is needed."] = "Los cambios esperan hasta que elijas Aplicar; Revertir los descarta. No es necesario reiniciar el juego.",
    ["Pending: {voice}"] = "Pendiente: {voice}",
    ["Natural speech"] = "Habla natural",
    ["Let companions speak the way a real person with their personality would: now and then a pause, a hesitation, a laugh or a sigh. Each character decides when it fits, and it stays rare; a fluent, confident speaker will hardly use it. OmniVoice can voice laughs and sighs; Pocket TTS uses only pauses in the sentence. It needs a local voice, so applying it while Convai cloud voice is chosen switches Companion voices to Pocket TTS. Off by default."] = "Deja que los compañeros hablen como lo haría una persona real con su personalidad: de vez en cuando una pausa, una duda, una risa o un suspiro. Cada personaje decide cuándo encaja y sigue siendo poco frecuente; quien habla con fluidez y seguridad casi no lo usa. OmniVoice puede reproducir risas y suspiros; Pocket TTS solo usa pausas dentro de la frase. Necesita una voz local: si lo aplicas con la voz en la nube de Convai elegida, las voces de compañeros cambian a Pocket TTS. Desactivado por defecto.",
    ["Natural speech needs a local voice, so {setting} was switched to {voice}."] = "El habla natural necesita una voz local, así que {setting} se cambió a {voice}.",
    ["Expressive emotions"] = "Emociones expresivas",
    ["Let each character mark its own feelings as it speaks, so the face changes when that part is spoken instead of being guessed from the words. Subtle by default, chosen by personality, and only where the feeling really shifts. It needs a local voice, so applying it while Convai cloud voice is chosen switches Companion voices to Pocket TTS. A reply without marks uses the usual text-based expression. Off by default."] = "Deja que cada personaje marque sus propios sentimientos al hablar, para que el rostro cambie justo cuando se dice esa parte, en lugar de deducirlo de las palabras. Sutil por defecto, elegido según la personalidad y solo donde el sentimiento cambia de verdad. Necesita una voz local: si lo aplicas con la voz en la nube de Convai elegida, las voces de compañeros cambian a Pocket TTS. Una respuesta sin marcas usa la expresión habitual basada en el texto. Desactivado por defecto.",
    ["Expressive emotions need a local voice, so {setting} was switched to {voice}."] = "Las emociones expresivas necesitan una voz local, así que {setting} se cambió a {voice}.",
}
